  assert.equal(item.setup.renderer.isDestroyed, false);
  assert.equal(item.app.session.events.at(-1)?.type, 'turn.cancelled');
  assert.equal(item.setup.renderer.isDestroyed, false);
  item.setup.mockInput.pressCtrlC();
  assert.equal(item.setup.renderer.isDestroyed, true);
