import {
  GeorgeError,
  cancellationError,
  validateModelId,
  validateProviderBaseUrl,
  type ModelProvider,
  type ProviderEvent,
  type ProviderRequest,
  type ProviderStreamOptions,
  type ProviderUsage,
} from '../core/index.ts';

export const DEFAULT_PROVIDER_TIMEOUT_MS = 30_000;
export const MAX_PROVIDER_TIMEOUT_MS = 120_000;

type SseMessage = Readonly<{ event?: string; data: string }>;

export type LmStudioProviderConfig = Readonly<{
  baseUrl: URL | string;
  model?: string;
  timeoutMs?: number;
}>;

function providerError(message: string, cause?: unknown): GeorgeError {
  return new GeorgeError('provider', message, cause === undefined ? undefined : { cause });
}

function timeoutMs(value: number | undefined): number {
  const timeout = value ?? DEFAULT_PROVIDER_TIMEOUT_MS;
  if (!Number.isInteger(timeout) || timeout < 1 || timeout > MAX_PROVIDER_TIMEOUT_MS) {
    throw new GeorgeError(
      'configuration',
      `Provider timeout must be an integer between 1 and ${MAX_PROVIDER_TIMEOUT_MS} ms.`,
    );
  }
  return timeout;
}

function usageFrom(value: unknown): ProviderUsage | undefined {
  if (!value || typeof value !== 'object') return undefined;
  const usage = value as Record<string, unknown>;
  const inputTokens = usage.input_tokens;
  const outputTokens = usage.output_tokens;
  const normalized = {
    ...(typeof inputTokens === 'number' && Number.isFinite(inputTokens)
      ? { inputTokens }
      : {}),
    ...(typeof outputTokens === 'number' && Number.isFinite(outputTokens)
      ? { outputTokens }
      : {}),
  };
  return Object.keys(normalized).length === 0 ? undefined : normalized;
}

function stringAt(value: unknown, key: string): string | undefined {
  if (!value || typeof value !== 'object') return undefined;
  const candidate = (value as Record<string, unknown>)[key];
  return typeof candidate === 'string' ? candidate : undefined;
}

function functionCallFrom(value: unknown): Extract<ProviderEvent, { type: 'provider.tool.call' }> | undefined {
  const item = value && typeof value === 'object' && 'item' in value
    ? (value as { item: unknown }).item
    : value;
  if (stringAt(item, 'type') !== 'function_call') return undefined;
  const callId = stringAt(item, 'call_id');
  const name = stringAt(item, 'name');
  const arguments_ = stringAt(item, 'arguments');
  if (!callId || !name || arguments_ === undefined) {
    throw providerError('LM Studio sent an incomplete function call.');
  }
  return { type: 'provider.tool.call', callId, name, arguments: arguments_ };
}

function normalizeMessage(message: SseMessage): ProviderEvent | undefined {
  if (message.data === '[DONE]') return undefined;

  let payload: unknown;
  try {
    payload = JSON.parse(message.data);
  } catch {
    throw providerError('LM Studio sent malformed SSE JSON.');
  }
  if (!payload || typeof payload !== 'object') {
    throw providerError('LM Studio sent an invalid SSE event payload.');
  }

  const wireType = message.event && message.event !== 'message'
    ? message.event
    : stringAt(payload, 'type');
  const response = (payload as Record<string, unknown>).response;
  switch (wireType) {
    case 'response.created':
      return {
        type: 'provider.response.started',
        ...(stringAt(response, 'id') ? { responseId: stringAt(response, 'id') } : {}),
      };
    case 'response.output_text.delta': {
      const delta = stringAt(payload, 'delta');
      if (delta === undefined) throw providerError('LM Studio sent a text delta without text.');
      return { type: 'provider.text.delta', delta };
    }
    case 'response.function_call_arguments.done': {
      const callId = stringAt(payload, 'call_id');
      const name = stringAt(payload, 'name');
      const arguments_ = stringAt(payload, 'arguments');
      if (!callId || !name || arguments_ === undefined) {
        throw providerError('LM Studio sent an incomplete function call.');
      }
      return { type: 'provider.tool.call', callId, name, arguments: arguments_ };
    }
    case 'response.output_item.done':
      return functionCallFrom(payload);
    case 'response.completed': {
      const responseUsage = response && typeof response === 'object'
        ? (response as Record<string, unknown>).usage
        : undefined;
      const usage = usageFrom(responseUsage) ?? usageFrom((payload as Record<string, unknown>).usage);
      return { type: 'provider.response.completed', ...(usage === undefined ? {} : { usage }) };
    }
    case 'error':
    case 'response.failed':
    case 'response.incomplete':
      throw providerError('LM Studio reported a provider error.', { event: wireType });
    default:
      return undefined;
  }
}

/** Parse SSE frames without assuming network chunk boundaries. */
export async function* parseSse(
  body: ReadableStream<Uint8Array>,
): AsyncGenerator<SseMessage> {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let event: string | undefined;
  let data: string[] = [];

  const processLine = (line: string): SseMessage | undefined => {
    if (line === '') {
      const message = data.length === 0
        ? undefined
        : { ...(event === undefined ? {} : { event }), data: data.join('\n') };
      event = undefined;
      data = [];
      return message;
    }
    if (line.startsWith(':')) return undefined;
    const colon = line.indexOf(':');
    const field = colon === -1 ? line : line.slice(0, colon);
    const value = colon === -1 ? '' : line.slice(colon + 1).replace(/^ /, '');
    if (field === 'event') event = value;
    if (field === 'data') data.push(value);
    return undefined;
  };

  try {
    while (true) {
      const { done, value } = await reader.read();
      buffer += decoder.decode(value, { stream: !done });
      let newline: number;
      while ((newline = buffer.indexOf('\n')) !== -1) {
        const rawLine = buffer.slice(0, newline);
        buffer = buffer.slice(newline + 1);
        const message = processLine(rawLine.endsWith('\r') ? rawLine.slice(0, -1) : rawLine);
        if (message) yield message;
      }
      if (done) break;
    }
  } finally {
    reader.releaseLock();
  }
  if (buffer || data.length > 0 || event !== undefined) {
    throw providerError('LM Studio closed an incomplete SSE event.');
  }
}

export class LmStudioResponsesProvider implements ModelProvider {
  readonly baseUrl: URL;
  readonly model: string | undefined;
  readonly defaultTimeoutMs: number;

  constructor(config: LmStudioProviderConfig) {
    this.baseUrl = validateProviderBaseUrl(config.baseUrl);
    this.model = config.model === undefined ? undefined : validateModelId(config.model);
    this.defaultTimeoutMs = timeoutMs(config.timeoutMs);
  }

  async *stream(
    request: ProviderRequest,
    options: ProviderStreamOptions = {},
  ): AsyncGenerator<ProviderEvent> {
    if (!this.model) {
      const error = new GeorgeError('configuration', 'LM Studio model ID is required.');
      yield { type: 'provider.error', error };
      throw error;
    }
    const requestTimeout = timeoutMs(options.timeoutMs ?? this.defaultTimeoutMs);
    const timeoutController = new AbortController();
    const timer = setTimeout(() => timeoutController.abort(), requestTimeout);
    const signal = options.signal
      ? AbortSignal.any([options.signal, timeoutController.signal])
      : timeoutController.signal;

    const failure = (error: unknown): GeorgeError => {
      if (options.signal?.aborted) {
        return cancellationError(options.signal) ?? new GeorgeError('cancelled', 'Operation cancelled.');
      }
      if (timeoutController.signal.aborted) {
        return providerError(`LM Studio request timed out after ${requestTimeout} ms.`, {
          kind: 'timeout',
        });
      }
      return error instanceof GeorgeError ? error : providerError('LM Studio request failed.', error);
    };

    try {
      let response: Response;
      try {
        response = await fetch(new URL('/v1/responses', this.baseUrl), {
          method: 'POST',
          headers: { 'content-type': 'application/json', accept: 'text/event-stream' },
          body: JSON.stringify({
            model: this.model,
            ...(request.instructions === undefined ? {} : { instructions: request.instructions }),
            input: request.input,
            stream: true,
          }),
          signal,
        });
      } catch (error) {
        const normalized = failure(error);
        yield { type: 'provider.error', error: normalized };
        throw normalized;
      }
      if (!response.ok) {
        const error = providerError(`LM Studio returned HTTP ${response.status}.`, {
          kind: 'http',
          status: response.status,
        });
        yield { type: 'provider.error', error };
        throw error;
      }
      if (!response.body) {
        const error = providerError('LM Studio returned an empty response body.');
        yield { type: 'provider.error', error };
        throw error;
      }

      let completed = false;
      const callIds = new Set<string>();
      try {
        for await (const message of parseSse(response.body)) {
          const event = normalizeMessage(message);
          if (!event) continue;
          if (event.type === 'provider.response.completed') completed = true;
          if (event.type === 'provider.tool.call') {
            if (callIds.has(event.callId)) continue;
            callIds.add(event.callId);
          }
          yield event;
        }
      } catch (error) {
        const normalized = failure(error);
        yield { type: 'provider.error', error: normalized };
        throw normalized;
      }
      if (!completed) {
        const error = providerError('LM Studio stream ended without a completion event.');
        yield { type: 'provider.error', error };
        throw error;
      }
    } finally {
      clearTimeout(timer);
    }
  }
}
--- src/tools/read-only.ts
import { open, opendir, stat } from 'node:fs/promises';
import { spawn } from 'node:child_process';
import { relative } from 'node:path';

import {
  GeorgeError,
  assertCanonicalWorkspace,
  cancellationError,
  resolveWorkspacePath,
  type Workspace,
} from '../core/index.ts';

export const READ_ONLY_TOOL_DEFINITIONS = [
  { name: 'read_file', description: 'Read a bounded text file from the workspace.' },
  { name: 'list_directory', description: 'List bounded direct entries in a workspace directory.' },
  { name: 'search_text', description: 'Search bounded workspace text without executing a shell.' },
  { name: 'git_status', description: 'Read Git status using a fixed read-only command.' },
  { name: 'git_diff', description: 'Read Git diff using a fixed read-only command.' },
] as const;

export type ReadOnlyToolCall =
  | Readonly<{ name: 'read_file'; path: string }>
  | Readonly<{ name: 'list_directory'; path: string }>
  | Readonly<{ name: 'search_text'; query: string; path?: string }>
  | Readonly<{ name: 'git_status' }>
  | Readonly<{ name: 'git_diff' }>;

export type ReadOnlyToolResult =
  | Readonly<{ name: 'read_file'; path: string; text: string; bytes: number; truncated: boolean }>
  | Readonly<{
      name: 'list_directory';
      path: string;
      entries: readonly Readonly<{ name: string; kind: 'file' | 'directory' | 'symlink' | 'other' }>[];
      truncated: boolean;
    }>
  | Readonly<{
      name: 'search_text';
      path: string;
      matches: readonly Readonly<{ path: string; line: number; text: string }>[];
      scannedFiles: number;
      scannedBytes: number;
      truncated: boolean;
    }>
  | GitResult;

export type GitResult = Readonly<{
  name: 'git_status' | 'git_diff';
  stdout: string;
  stderr: string;
  exitCode: number | null;
  stdoutTruncated: boolean;
  stderrTruncated: boolean;
}>;

export type ReadOnlyToolLimits = Readonly<{
  maxReadBytes?: number;
  maxListEntries?: number;
  maxSearchFiles?: number;
  maxSearchBytes?: number;
  maxSearchResults?: number;
  maxGitOutputBytes?: number;
  gitTimeoutMs?: number;
}>;

type Limits = Required<ReadOnlyToolLimits>;

const DEFAULT_LIMITS: Limits = {
  maxReadBytes: 64 * 1024,
  maxListEntries: 256,
  maxSearchFiles: 1_000,
  maxSearchBytes: 1024 * 1024,
  maxSearchResults: 100,
  maxGitOutputBytes: 256 * 1024,
  gitTimeoutMs: 10_000,
};

const MAX_LIMITS: Limits = {
  maxReadBytes: 1024 * 1024,
  maxListEntries: 10_000,
  maxSearchFiles: 10_000,
  maxSearchBytes: 16 * 1024 * 1024,
  maxSearchResults: 1_000,
  maxGitOutputBytes: 1024 * 1024,
  gitTimeoutMs: 30_000,
};

function limits(input: ReadOnlyToolLimits): Limits {
  return Object.fromEntries(Object.entries(DEFAULT_LIMITS).map(([key, fallback]) => {
    const value = input[key as keyof ReadOnlyToolLimits] ?? fallback;
    const maximum = MAX_LIMITS[key as keyof Limits];
    if (!Number.isInteger(value) || value < 1) {
      throw new GeorgeError('configuration', `${key} must be a positive integer.`);
    }
    return [key, Math.min(value, maximum)];
  })) as Limits;
}

async function boundedRead(path: string, maxBytes: number): Promise<{ text: string; bytes: number; truncated: boolean }> {
  const handle = await open(path, 'r');
  try {
    const buffer = Buffer.alloc(maxBytes + 1);
    const { bytesRead } = await handle.read(buffer, 0, buffer.length, 0);
    const bytes = Math.min(bytesRead, maxBytes);
    return { text: buffer.subarray(0, bytes).toString('utf8'), bytes, truncated: bytesRead > maxBytes };
  } finally {
    await handle.close();
  }
}

function relativePath(workspace: Workspace, path: string): string {
  return relative(workspace.root, path) || '.';
}

async function runGit(
  workspace: Workspace,
  args: readonly string[],
  outputLimit: number,
  timeoutMs: number,
  signal?: AbortSignal,
): Promise<Omit<GitResult, 'name'>> {
  return new Promise((resolve, reject) => {
    const child = spawn('git', args, { cwd: workspace.root, shell: false, stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout: Buffer<ArrayBufferLike> = Buffer.alloc(0);
    let stderr: Buffer<ArrayBufferLike> = Buffer.alloc(0);
    let stdoutTruncated = false;
    let stderrTruncated = false;
    let timedOut = false;
    const append = (current: Buffer<ArrayBufferLike>, chunk: Buffer<ArrayBufferLike>, mark: (value: boolean) => void): Buffer<ArrayBufferLike> => {
      if (current.length >= outputLimit) {
        mark(true);
        return current;
      }
      const next = Buffer.concat([current, chunk.subarray(0, outputLimit - current.length)]);
      if (next.length < current.length + chunk.length) mark(true);
      return next;
    };
    const timeout = setTimeout(() => { timedOut = true; child.kill(); }, timeoutMs);
    const cancelled = () => child.kill();
    signal?.addEventListener('abort', cancelled, { once: true });
    child.stdout.on('data', (chunk: Buffer) => { stdout = append(stdout, chunk, (value) => { stdoutTruncated = value; }); });
    child.stderr.on('data', (chunk: Buffer) => { stderr = append(stderr, chunk, (value) => { stderrTruncated = value; }); });
    child.on('error', (error) => {
      clearTimeout(timeout);
      signal?.removeEventListener('abort', cancelled);
      reject(signal?.aborted
        ? cancellationError(signal)
        : new GeorgeError('tool', 'Unable to start read-only Git.', { cause: error }));
    });
    child.on('close', (exitCode) => {
      clearTimeout(timeout);
      signal?.removeEventListener('abort', cancelled);
      if (signal?.aborted) return reject(cancellationError(signal));
      if (timedOut) return reject(new GeorgeError('tool', `Read-only Git timed out after ${timeoutMs} ms.`));
      resolve({ stdout: stdout.toString('utf8'), stderr: stderr.toString('utf8'), exitCode, stdoutTruncated, stderrTruncated });
    });
  });
}

export type ReadOnlyToolExecutor = Readonly<{
  workspace: Workspace;
  definitions: typeof READ_ONLY_TOOL_DEFINITIONS;
  execute: (call: ReadOnlyToolCall, options?: Readonly<{ signal?: AbortSignal }>) => Promise<ReadOnlyToolResult>;
}>;

export function createReadOnlyToolExecutor(
  workspace: Workspace,
  configuredLimits: ReadOnlyToolLimits = {},
): ReadOnlyToolExecutor {
  const bounded = limits(configuredLimits);
  const execute = async (call: ReadOnlyToolCall, options: Readonly<{ signal?: AbortSignal }> = {}): Promise<ReadOnlyToolResult> => {
    if (options.signal?.aborted) throw cancellationError(options.signal);
    await assertCanonicalWorkspace(workspace);
    switch (call.name) {
      case 'read_file': {
        const path = await resolveWorkspacePath(workspace, call.path);
        if (!(await stat(path)).isFile()) throw new GeorgeError('validation', 'Path must name a file.');
        return { name: call.name, path: relativePath(workspace, path), ...await boundedRead(path, bounded.maxReadBytes) };
      }
      case 'list_directory': {
        const path = await resolveWorkspacePath(workspace, call.path);
        if (!(await stat(path)).isDirectory()) throw new GeorgeError('validation', 'Path must name a directory.');
        const directory = await opendir(path);
        const entries: Array<{ name: string; kind: 'file' | 'directory' | 'symlink' | 'other' }> = [];
        let truncated = false;
        try {
          for await (const entry of directory) {
            if (entries.length === bounded.maxListEntries) { truncated = true; break; }
            entries.push({
              name: entry.name,
              kind: entry.isFile() ? 'file' : entry.isDirectory() ? 'directory' : entry.isSymbolicLink() ? 'symlink' : 'other',
            });
          }
        } finally {
          await directory.close().catch(() => undefined);
        }
        return { name: call.name, path: relativePath(workspace, path), entries, truncated };
      }
      case 'search_text': {
        if (!call.query) throw new GeorgeError('validation', 'Search query must not be empty.');
        const root = await resolveWorkspacePath(workspace, call.path ?? '.');
        if (!(await stat(root)).isDirectory()) throw new GeorgeError('validation', 'Search path must name a directory.');
        const matches: Array<{ path: string; line: number; text: string }> = [];
        let scannedFiles = 0;
        let scannedBytes = 0;
        let truncated = false;
        const walk = async (directory: string): Promise<void> => {
          const handle = await opendir(directory);
          try {
            for await (const entry of handle) {
              if (truncated) return;
              const path = `${directory}/${entry.name}`;
              if (entry.isSymbolicLink()) continue;
              if (entry.isDirectory()) await walk(path);
              if (!entry.isFile()) continue;
              if (scannedFiles === bounded.maxSearchFiles || scannedBytes === bounded.maxSearchBytes) { truncated = true; return; }
              const available = bounded.maxSearchBytes - scannedBytes;
              const content = await boundedRead(path, available);
              scannedFiles += 1;
              scannedBytes += content.bytes;
              if (content.truncated) truncated = true;
              for (const [index, text] of content.text.split(/\r?\n/).entries()) {
                if (text.includes(call.query)) matches.push({ path: relativePath(workspace, path), line: index + 1, text });
                if (matches.length === bounded.maxSearchResults) { truncated = true; return; }
              }
            }
          } finally {
            await handle.close().catch(() => undefined);
          }
        };
        await walk(root);
        return { name: call.name, path: relativePath(workspace, root), matches, scannedFiles, scannedBytes, truncated };
      }
      case 'git_status':
        return { name: call.name, ...await runGit(workspace, ['status', '--short', '--branch'], bounded.maxGitOutputBytes, bounded.gitTimeoutMs, options.signal) };
      case 'git_diff':
        return { name: call.name, ...await runGit(workspace, ['diff', '--no-ext-diff'], bounded.maxGitOutputBytes, bounded.gitTimeoutMs, options.signal) };
    }
  };
  return { workspace, definitions: READ_ONLY_TOOL_DEFINITIONS, execute };
}
